// guardedAllocationRepository keeps Allocation's references whole; see guard.
type guardedAllocationRepository struct {
	AllocationRepository
	refs *repox.References
}

func (g *guardedAllocationRepository) Delete(ctx context.Context, name string) error {
	check, err := g.refs.CheckDelete(ctx, "freebusy.allocation.v1/Allocation", name)
	if err != nil {
		return err
	}
	if err := g.AllocationRepository.Delete(ctx, name); err != nil {
		return err
	}
	check.Done(ctx, true)
	return nil
}

// resolveAllocationReferences proves, through refs, that every external
// reference m sets within paths (all of them for an empty mask) names a
// resource that exists.
func resolveAllocationReferences(ctx context.Context, refs *repox.References, m *allocationpbv1.Allocation, paths []string) error {
	return nil
}

// queueAllocationReferences makes u resolve m's external references within
// paths before it commits, as guard does for the repositories.
func queueAllocationReferences(u *repox.Unit, m *allocationpbv1.Allocation, paths []string) {
}

// queueAllocationDelete makes u consult name's referrers before it commits
// and publish the NOTIFY event after, as guard does for Delete.
func queueAllocationDelete(u *repox.Unit, name string, purged bool) {
	refs := u.Conn().References
	if refs == nil {
		return
	}
	var check *repox.DeleteCheck
	u.Before(func(ctx context.Context) (err error) {
		check, err = refs.CheckDelete(ctx, "freebusy.allocation.v1/Allocation", name)
		return err
	})
	u.After(func(ctx context.Context) { check.Done(ctx, purged) })
}

